// Expansion: every active prompt x every model x N_RUNS repetitions.
// One output item = one upcoming API call.

const MODELS = [
  { model: 'perplexity/sonar', plugins: null },
  { model: 'openai/gpt-4o-mini', plugins: [{ id: 'web', engine: 'native' }] },
  { model: 'google/gemini-2.5-flash', plugins: [{ id: 'web', engine: 'native' }] },
  { model: 'anthropic/claude-sonnet-4.5', plugins: [{ id: 'web', engine: 'native' }] }
];
const N_RUNS = 3;

const today = new Date().toISOString().slice(0, 10);
const out = [];

for (const item of $input.all()) {
  const p = item.json;
  if (String(p.active).toUpperCase() !== 'TRUE') continue;

  for (const m of MODELS) {
    for (let i = 1; i <= N_RUNS; i++) {
      const body = {
        model: m.model,
        messages: [{ role: 'user', content: p.text }],
        max_tokens: 1024
      };
      if (m.plugins) body.plugins = m.plugins;

      const modelShort = m.model.split('/')[1].replace(/[^a-z0-9.-]/gi, '');
      out.push({ json: {
        run_id: `${today}_${p.prompt_id}_${modelShort}_${i}`,
        prompt_id: p.prompt_id,
        prompt_text: p.text,
        model: m.model,
        run_index: i,
        request_body: body
      }});
    }
  }
}

return out;

// Normalize the OpenRouter response into the unified schema for the runs tab.
// Sources: annotations[].url_citation.url (OpenRouter standard for all models),
// fallback to resp.citations (legacy Perplexity field).

const meta = $('Loop Over Items').item.json;
const resp = $input.item.json;

let answer = '';
let citations = [];
let status = 'ok';

if (resp && resp.error) {
  status = 'error: ' + String(resp.error.message || JSON.stringify(resp.error)).slice(0, 200);
} else {
  const msg = (resp && resp.choices && resp.choices[0] && resp.choices[0].message) || {};
  answer = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content || '');

  if (Array.isArray(msg.annotations)) {
    citations = msg.annotations
      .filter(a => a.type === 'url_citation')
      .map(a => (a.url_citation && a.url_citation.url) || a.url)
      .filter(Boolean);
  }
  if (citations.length === 0 && Array.isArray(resp.citations)) {
    citations = resp.citations;
  }
  if (!answer) status = 'empty';
}

return [{ json: {
  run_id: meta.run_id,
  timestamp: new Date().toISOString(),
  model: meta.model,
  prompt_id: meta.prompt_id,
  run_index: meta.run_index,
  status,
  answer_text: answer.slice(0, 45000),
  citations_json: JSON.stringify([...new Set(citations)])
}}];

// Mention and citation analysis: only today's runs with status=ok.
// Fully deterministic, no LLM judge. One row = one brand in one run.

const brands = $('Read Brands').all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!String(r.run_id || '').startsWith(today)) continue;
  if (String(r.status || '') !== 'ok') continue;

  const text = String(r.answer_text || '');
  let cites = [];
  try { cites = JSON.parse(r.citations_json || '[]'); } catch (e) { cites = []; }

  for (const b of brands) {
    let re;
    try {
      re = new RegExp(b.aliases_regex, 'i');
    } catch (e) {
      re = new RegExp(String(b.name || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    }
    const m = text.match(re);
    const domains = String(b.domains || '').split(',').map(d => d.trim()).filter(Boolean);

    out.push({ json: {
      run_id: r.run_id,
      model: r.model,
      prompt_id: r.prompt_id,
      brand_id: b.brand_id,
      brand_name: b.name,
      is_own: String(b.is_own).toUpperCase() === 'TRUE',
      mentioned: !!m,
      cited: cites.some(u => domains.some(d => String(u).includes(d))),
      first_position: m ? +(m.index / Math.max(text.length, 1)).toFixed(3) : ''
    }});
  }
}

return out;

// Weekly aggregation per model x brand plus a combined value across all models ('all').
// mention_rate = runs with a mention / all runs
// citation_rate = runs with a domain citation / all runs
// sov = brand mentions / sum of mentions across all brands
// avg_position = mean relative position of the first mention (0 = start of the answer)

const rows = $('Detect Mentions').all().map(i => i.json);
if (rows.length === 0) return [];

function isoWeek(d) {
  const dt = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day = dt.getUTCDay() || 7;
  dt.setUTCDate(dt.getUTCDate() + 4 - day);
  const year = dt.getUTCFullYear();
  const start = new Date(Date.UTC(year, 0, 1));
  const week = Math.ceil((((dt - start) / 86400000) + 1) / 7);
  return year + '-W' + String(week).padStart(2, '0');
}
const week = isoWeek(new Date());

const isTrue = v => v === true || String(v).toUpperCase() === 'TRUE';
const models = [...new Set(rows.map(r => r.model))];
models.push('all');

const out = [];
for (const model of models) {
  const subset = model === 'all' ? rows : rows.filter(r => r.model === model);
  const nRuns = new Set(subset.map(r => r.run_id)).size;
  const brandIds = [...new Set(subset.map(r => r.brand_id))];

  const stats = brandIds.map(bid => {
    const bRows = subset.filter(r => r.brand_id === bid);
    const mentions = bRows.filter(r => isTrue(r.mentioned));
    const cited = bRows.filter(r => isTrue(r.cited));
    const positions = mentions.map(r => parseFloat(r.first_position)).filter(v => !isNaN(v));
    return {
      bid,
      name: bRows[0].brand_name,
      is_own: isTrue(bRows[0].is_own),
      mentions: mentions.length,
      cited: cited.length,
      positions
    };
  });
  const totalMentions = stats.reduce((s, x) => s + x.mentions, 0);

  for (const st of stats) {
    out.push({ json: {
      week,
      model,
      brand_id: st.bid,
      brand_name: st.name,
      is_own: st.is_own,
      n_runs: nRuns,
      mention_rate: nRuns ? +(st.mentions / nRuns).toFixed(3) : 0,
      citation_rate: nRuns ? +(st.cited / nRuns).toFixed(3) : 0,
      sov: totalMentions ? +(st.mentions / totalMentions).toFixed(3) : 0,
      avg_position: st.positions.length ? +(st.positions.reduce((a, b) => a + b, 0) / st.positions.length).toFixed(3) : ''
    }});
  }
}

return out;

// HTML visibility report: own-brand overview per model, SoV ranking of all brands,
// alerts on a SoV drop of more than 5 percentage points or a Citation Rate of 0.
// Output: subject and html for the email delivery.

const agg = $input.all().map(i => i.json);
const current = $('Calculate Weekly Metrics').all().map(i => i.json);

const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const pct = v => Math.round(num(v) * 100) + '%';
const isTrue = v => v === true || String(v).toUpperCase() === 'TRUE';

if (current.length === 0) {
  return [{ json: {
    subject: 'GEO SoV Monitor: no data in this run',
    html: '<p>No usable data in this run. Please check the execution log in n8n.</p>'
  }}];
}

const week = current[0].week;
const prevWeeks = [...new Set(agg.map(r => String(r.week)).filter(w => w && w < week))].sort();
const prevWeek = prevWeeks[prevWeeks.length - 1] || null;
const prev = prevWeek ? agg.filter(r => String(r.week) === prevWeek) : [];

const findPrev = (bid, model) => prev.find(r => String(r.brand_id) === String(bid) && String(r.model) === String(model));
const deltaPp = (cur, field) => {
  const p = findPrev(cur.brand_id, cur.model);
  if (!p) return 'new';
  const d = Math.round((num(cur[field]) - num(p[field])) * 100);
  if (d > 0) return '+' + d + ' pp';
  if (d < 0) return d + ' pp';
  return '0 pp';
};

const ownRows = current.filter(r => isTrue(r.is_own));
const ownAll = ownRows.find(r => r.model === 'all');
const ownName = ownRows[0] ? ownRows[0].brand_name : 'Own brand';

const alerts = [];
if (prevWeek) {
  for (const cur of ownRows) {
    const p = findPrev(cur.brand_id, cur.model);
    if (!p) continue;
    if (num(cur.sov) - num(p.sov) <= -0.05) {
      alerts.push('SoV drop on ' + cur.model + ': from ' + pct(p.sov) + ' to ' + pct(cur.sov));
    }
    if (num(cur.citation_rate) === 0 && num(p.citation_rate) > 0) {
      alerts.push('Citation Rate on ' + cur.model + ' dropped to 0. Check crawler access to the domain (robots.txt, WAF, status codes).');
    }
  }
}

const td = `style='padding:6px 10px;border:1px solid #ddd;font-size:14px'`;
const th = `style='padding:6px 10px;border:1px solid #ddd;font-size:13px;background:#f2f2f2;text-align:left'`;

const modelOrder = ['all', ...[...new Set(current.map(r => r.model))].filter(m => m !== 'all').sort()];
let ownTable = '';
for (const m of modelOrder) {
  const r = ownRows.find(x => x.model === m);
  if (!r) continue;
  const label = m === 'all' ? '<strong>All models</strong>' : m;
  const posVal = r.avg_position !== '' && r.avg_position !== undefined ? num(r.avg_position).toFixed(2) : '-';
  ownTable += `<tr><td ${td}>${label}</td><td ${td}>${pct(r.sov)} (${deltaPp(r, 'sov')})</td><td ${td}>${pct(r.mention_rate)} (${deltaPp(r, 'mention_rate')})</td><td ${td}>${pct(r.citation_rate)} (${deltaPp(r, 'citation_rate')})</td><td ${td}>${posVal}</td></tr>`;
}

const ranking = current.filter(r => r.model === 'all').sort((a, b) => num(b.sov) - num(a.sov));
let rankTable = '';
ranking.forEach((r, i) => {
  const weight = isTrue(r.is_own) ? 'font-weight:bold;background:#f5faff' : '';
  rankTable += `<tr style='${weight}'><td ${td}>${i + 1}</td><td ${td}>${r.brand_name}</td><td ${td}>${pct(r.sov)} (${deltaPp(r, 'sov')})</td><td ${td}>${pct(r.mention_rate)}</td><td ${td}>${pct(r.citation_rate)}</td></tr>`;
});

const alertsHtml = alerts.length
  ? `<div style='background:#fdecea;border:1px solid #e57373;border-radius:6px;padding:12px 16px;margin:20px 0'><p style='margin:0;font-weight:bold'>Alerts</p><ul style='margin:8px 0 0;padding-left:20px'>` + alerts.map(a => `<li style='margin-bottom:4px'>${a}</li>`).join('') + `</ul></div>`
  : '';

const firstNote = prevWeek
  ? ''
  : `<p style='color:#666'>First measurement. Week-over-week values in parentheses will appear from next week on.</p>`;

const compareNote = prevWeek ? `<p style='color:#666;font-size:13px'>Values in parentheses: change vs. week ${prevWeek} in percentage points (pp).</p>` : '';

const html = `
<div style='font-family:Arial,Helvetica,sans-serif;color:#222;max-width:720px'>
  <h2 style='margin-bottom:4px'>AI Visibility Report, week ${week}</h2>
  <p style='margin-top:0;color:#666'>Brand: ${ownName}. Data basis: ${ownAll ? ownAll.n_runs : '?'} runs across ${modelOrder.length - 1} AI models.</p>
  ${firstNote}
  ${alertsHtml}
  <h3 style='margin-bottom:8px'>${ownName} by model</h3>
  <table style='border-collapse:collapse;width:100%'>
    <tr><th ${th}>Model</th><th ${th}>Share of Voice</th><th ${th}>Mention Rate</th><th ${th}>Citation Rate</th><th ${th}>Avg. Position</th></tr>
    ${ownTable}
  </table>
  <h3 style='margin-bottom:8px;margin-top:24px'>SoV ranking of all brands (all models)</h3>
  <table style='border-collapse:collapse;width:100%'>
    <tr><th ${th}>#</th><th ${th}>Brand</th><th ${th}>Share of Voice</th><th ${th}>Mention Rate</th><th ${th}>Citation Rate</th></tr>
    ${rankTable}
  </table>
  ${compareNote}
  <p style='color:#999;font-size:12px;margin-top:24px'>Automatically generated by the GEO SoV Monitor (n8n). Raw data and weekly metrics live in the connected Google Sheet.</p>
</div>`;

const subject = 'AI Visibility Report ' + week + ': ' + ownName + ' SoV ' + (ownAll ? pct(ownAll.sov) : 'n/a') + (alerts.length ? ' (' + alerts.length + ' alert' + (alerts.length > 1 ? 's' : '') + ')' : '');

return [{ json: { subject, html } }];
